import { Test } from '@nestjs/testing';
import type { INestApplication } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { AppModule } from '../src/app.module';

jest.setTimeout(30000);

/**
 * The database must enforce its own rules.
 *
 * `1791532862193-InventoryMasters` was generated by `typeorm migration:generate`
 * against entity classes that never declared the indexes and foreign keys the
 * earlier migrations wrote by hand. The generator read them as drift and
 * dropped 82 of them — unique voucher numbers, one active financial year, one
 * ledger per party, and about thirty foreign keys. Every e2e test still passed,
 * because the application code checks the same things in TypeScript.
 *
 * That is why this file exists: it asserts the *schema*, not the API. If a
 * future migration drops one of these again, this fails immediately.
 */
describe('Schema integrity (e2e)', () => {
  let app: INestApplication;
  let dataSource: DataSource;
  let indexes: Set<string>;
  let foreignKeys: Set<string>;

  beforeAll(async () => {
    const moduleRef = await Test.createTestingModule({ imports: [AppModule] }).compile();
    app = moduleRef.createNestApplication();
    await app.init();
    dataSource = app.get(DataSource);

    const idxRows: { name: string }[] = await dataSource.query(
      `SELECT i.relname AS name FROM pg_index x
         JOIN pg_class c ON c.oid = x.indrelid
         JOIN pg_class i ON i.oid = x.indexrelid
        WHERE c.relnamespace = 'public'::regnamespace AND NOT x.indisprimary`,
    );
    indexes = new Set(idxRows.map((r) => r.name));

    const fkRows: { name: string }[] = await dataSource.query(
      `SELECT conname AS name FROM pg_constraint
        WHERE contype = 'f' AND connamespace = 'public'::regnamespace`,
    );
    foreignKeys = new Set(fkRows.map((r) => r.name));
  });

  afterAll(async () => {
    await app.close();
  });

  describe('accounting guarantees (P2)', () => {
    it.each([
      ['UQ_vouchers_company_number', 'a voucher number cannot repeat — GST invoice numbering'],
      ['UQ_voucher_sequences_scope', 'one sequence row per company/FY/type, so numbering stays gapless'],
      ['UQ_vouchers_reversal_of', 'a voucher can be reversed once'],
      ['UQ_ledgers_company_name', 'no two ledgers share a name'],
      ['UQ_ledgers_company_code', 'no two ledgers share a code'],
      ['UQ_ledgers_party', 'a party has exactly one ledger'],
      ['UQ_ledger_groups_company_name', 'no two groups share a name'],
      ['UQ_voucher_types_company_code', 'no two voucher types share a code'],
    ])('enforces %s — %s', (name) => {
      expect(indexes.has(name)).toBe(true);
    });
  });

  describe('company and tenancy guarantees (P1)', () => {
    it.each([
      ['UQ_financial_years_one_active', 'only one financial year is active at a time'],
      ['UQ_sites_company_code', 'no two kilns of a company share a code'],
      ['UQ_roles_code_company', 'no two roles share a code'],
      ['uq_parties_company_name', 'no two parties of a company share a name'],
      ['uq_parties_ledger_id', 'a ledger belongs to one party'],
    ])('enforces %s — %s', (name) => {
      expect(indexes.has(name)).toBe(true);
    });
  });

  describe('master-data business keys (P3)', () => {
    it.each([
      'uq_units_company_name',
      'uq_units_company_abbrev',
      'uq_items_company_name',
      'uq_brick_types_company_grade',
      'uq_warehouses_site_name',
      'uq_transport_drivers_company_name',
      'uq_transport_vehicles_company_reg',
      'uq_tax_hsn_rates_company_code',
      'uq_labour_wage_rates_company_activity',
    ])('enforces %s', (name) => {
      expect(indexes.has(name)).toBe(true);
    });
  });

  describe('every tenant table is indexed and keyed on company_id', () => {
    const TENANT_TABLES = [
      'parties',
      'units',
      'items',
      'warehouses',
      'brick_types',
      'transport_drivers',
      'transport_vehicles',
      'tax_hsn_rates',
      'labour_wage_rates',
    ];

    it.each(TENANT_TABLES)('%s has an index on company_id', async (table) => {
      const rows = await dataSource.query<{ count: string }[]>(
        `SELECT count(*) AS count FROM pg_index x
           JOIN pg_class c ON c.oid = x.indrelid
          WHERE c.relname = $1
            AND pg_get_indexdef(x.indexrelid) LIKE '%company_id%'`,
        [table],
      );
      expect(Number(rows[0]?.count)).toBeGreaterThan(0);
    });

    it.each(TENANT_TABLES)('%s has a foreign key to companies', async (table) => {
      const rows = await dataSource.query<{ count: string }[]>(
        `SELECT count(*) AS count FROM pg_constraint
          WHERE contype = 'f'
            AND conrelid = $1::regclass
            AND confrelid = 'companies'::regclass`,
        [table],
      );
      expect(Number(rows[0]?.count)).toBeGreaterThan(0);
    });
  });

  describe('foreign keys between the masters', () => {
    it.each([
      ['fk_items_unit_id', 'an item names a real unit'],
      ['fk_items_hsn_id', 'an item names a real HSN rate'],
      ['fk_warehouses_site_id', 'a warehouse sits at a real kiln'],
      ['fk_transport_vehicles_party_id', 'a hired vehicle names a real transporter'],
    ])('enforces %s — %s', (name) => {
      expect(foreignKeys.has(name)).toBe(true);
    });
  });

  describe('check constraints still guard the money columns', () => {
    it.each([
      'CK_voucher_lines_one_side',
      'CK_voucher_lines_not_negative',
      'CK_ledgers_opening_one_side',
      'CK_ledgers_opening_not_negative',
      'chk_parties_opening_one_side',
      'chk_parties_opening_non_negative',
      'chk_companies_gst_scheme',
    ])('enforces %s', async (name) => {
      const rows = await dataSource.query<{ count: string }[]>(
        `SELECT count(*) AS count FROM pg_constraint WHERE contype = 'c' AND conname = $1`,
        [name],
      );
      expect(Number(rows[0]?.count)).toBe(1);
    });
  });

  describe('the database actually refuses a violation', () => {
    it('rejects a second active financial year for one company', async () => {
      const created = await dataSource.query<{ id: string }[]>(
        `INSERT INTO companies (name, state_code) VALUES ('Schema Test Co', '09') RETURNING id`,
      );
      const companyId = created[0]!.id;

      const insertYear = (name: string, start: string, end: string) =>
        dataSource.query(
          `INSERT INTO financial_years (company_id, name, start_date, end_date, is_active, is_locked)
           VALUES ($1, $2, $3, $4, true, false)`,
          [companyId, name, start, end],
        );

      try {
        await insertYear('2026-27', '2026-04-01', '2027-03-31');
        await expect(insertYear('2027-28', '2027-04-01', '2028-03-31')).rejects.toThrow();
      } finally {
        await dataSource.query(`DELETE FROM financial_years WHERE company_id = $1`, [companyId]);
        await dataSource.query(`DELETE FROM companies WHERE id = $1`, [companyId]);
      }
    });

    it('rejects a unit whose company does not exist', async () => {
      await expect(
        dataSource.query(
          `INSERT INTO units (company_id, name, abbreviation)
           VALUES ('00000000-0000-4000-8000-000000000000', 'Ghost', 'gh')`,
        ),
      ).rejects.toThrow();
    });
  });
});
